// ============================================
// Work page: shows the three categories, then the
// list for the one you click.
// You do not edit this file. Add projects in the
// files inside the work/ folders.
// ============================================

const categories = [
  { key: "automation",     name: "Automation",     list: typeof automationProjects !== "undefined" ? automationProjects : [] },
  { key: "data-analytics", name: "Data Analytics", list: typeof analyticsProjects  !== "undefined" ? analyticsProjects  : [] },
  { key: "websites",       name: "Website",        list: typeof websiteProjects    !== "undefined" ? websiteProjects    : [] }
];

const catsBox = document.getElementById("cats");
const results = document.getElementById("results");
const resultsTitle = document.getElementById("results-title");
const workList = document.getElementById("work-list");

function pad(n) {
  return String(n).padStart(2, "0");
}

// ---------- The three category boxes ----------
categories.forEach(function (c, i) {
  const box = document.createElement("a");
  box.className = "cat";
  box.href = "#" + c.key;

  const num = document.createElement("span");
  num.className = "tag";
  num.textContent = pad(i + 1);

  const body = document.createElement("div");

  const name = document.createElement("h2");
  name.textContent = c.name;

  const count = document.createElement("p");
  if (c.list.length === 0) {
    count.textContent = "Coming soon";
  } else {
    count.textContent = c.list.length + (c.list.length === 1 ? " project" : " projects");
  }

  body.append(name, count);

  const arrow = document.createElement("span");
  arrow.className = "arrow cat-arrow";
  arrow.textContent = "→";

  box.append(num, body, arrow);
  catsBox.append(box);
});

// ---------- Show the list for one category ----------
function showList(cat, pickId) {
  catsBox.hidden = true;
  results.hidden = false;
  resultsTitle.textContent = cat.name;
  workList.textContent = "";

  if (cat.list.length === 0) {
    const empty = document.createElement("p");
    empty.className = "empty";
    empty.textContent = "Coming soon. Projects will appear here.";
    workList.append(empty);
    return;
  }

  let pickRow = null;

  cat.list.forEach(function (p, i) {
    const row = document.createElement("article");
    row.className = "work-row" + (p.link ? " live" : "");
    row.id = p.id || "";

    if (p.id && p.id === pickId) {
      row.classList.add("pick");
      pickRow = row;
    }

    const num = document.createElement("span");
    num.className = "tag";
    num.textContent = pad(i + 1);

    const info = document.createElement("div");

    const title = document.createElement("h3");
    title.textContent = p.title;

    const text = document.createElement("p");
    text.textContent = p.summary;

    info.append(title, text);
    row.append(num, info);

    if (p.link) {
      const a = document.createElement("a");
      a.className = "row-link";
      a.href = p.link;
      a.textContent = "View project →";
      if (/^https?:/.test(p.link)) {
        a.target = "_blank";
        a.rel = "noopener noreferrer";
      }
      row.append(a);
    } else {
      const status = document.createElement("span");
      status.className = "row-status";
      status.textContent = "Link coming soon";
      row.append(status);
    }

    workList.append(row);
  });

  if (pickRow) {
    pickRow.scrollIntoView({ block: "center" });
  }
}

function showCats() {
  results.hidden = true;
  catsBox.hidden = false;
}

// ---------- Which view to show (based on the address) ----------
// work.html                       -> the three boxes
// work.html#automation            -> the automation list
// work.html#automation/some-id    -> the list, with that project marked
function route() {
  const parts = location.hash.replace("#", "").split("/");
  const cat = categories.find(function (c) {
    return c.key === parts[0];
  });

  if (cat) {
    showList(cat, parts[1]);
  } else {
    showCats();
  }
}

window.addEventListener("hashchange", route);
route();

// ---------- Resume ----------
// If resume/resume.pdf exists, a download button appears.
// To update your resume, replace that file. Keep the same name.
const resumeStatus = document.getElementById("resume-status");
const resumeText = document.getElementById("resume-text");

if (resumeStatus) {
  fetch("resume/resume.pdf", { method: "HEAD" })
    .then(function (res) {
      if (!res.ok) return;

      const a = document.createElement("a");
      a.href = "resume/resume.pdf";
      a.className = "talk";
      a.setAttribute("download", "");

      const arrow = document.createElement("span");
      arrow.className = "arrow";
      arrow.textContent = "↓";

      const label = document.createElement("span");
      label.className = "talk-text";
      label.textContent = "Download resume";

      a.append(arrow, label);
      resumeStatus.replaceWith(a);
      resumeText.textContent = "Download my latest resume as a PDF.";
    })
    .catch(function () {});
}